use rtla::parse_module;

#[test]
fn named_instances_keep_parameters_in_modules_and_let_scopes() {
    let module = serde_json::to_value(parse_module("---- MODULE Root ----\nA(n, F(_)) == INSTANCE Counter WITH Limit <- n, Transform <- F\nInit == LET B(n) == INSTANCE Counter WITH Limit <- n IN B(2)!Init\n====").unwrap()).unwrap();
    assert_eq!(module["instances"][0]["params"][0]["name"], "n");
    assert_eq!(module["instances"][0]["params"][1]["arity"], 1);
    let local = &module["definitions"][0]["body"];
    assert_eq!(local["kind"], "LetModule");
    assert_eq!(local["instances"][0]["name"], "B");
    assert_eq!(local["body"]["kind"], "Selection");
}

#[test]
fn recursive_declarations_keep_arity_and_mark_the_corresponding_definitions() {
    let module = serde_json::to_value(parse_module("---- MODULE Root ----\nRECURSIVE Fact(_), Even(_), Odd(_)\nFact(n) == IF n = 0 THEN 1 ELSE n * Fact(n-1)\nEven(n) == IF n = 0 THEN TRUE ELSE Odd(n-1)\nOdd(n) == IF n = 0 THEN FALSE ELSE Even(n-1)\nLocal == LET RECURSIVE F(_) F(n) == IF n=0 THEN 0 ELSE F(n-1) IN F(2)\n====").unwrap()).unwrap();
    assert_eq!(module["recursive"].as_array().unwrap().len(), 3);
    assert_eq!(module["recursive"][0]["arity"], 1);
    assert_eq!(module["definitions"][0]["isRecursive"], true);
    assert_eq!(
        module["definitions"][3]["body"]["definitions"][0]["isRecursive"],
        true
    );
}

#[test]
fn nested_modules_preserve_the_outer_module_after_the_inner_terminator() {
    let module = serde_json::to_value(parse_module("---- MODULE Root ----\nCONSTANT N\n---- MODULE Inner ----\nValue == N\n====\nI == INSTANCE Inner\nResult == I!Value\n====\nignored epilogue").unwrap()).unwrap();
    assert_eq!(module["modules"][0]["name"], "Inner");
    assert_eq!(module["modules"][0]["definitions"][0]["name"], "Value");
    assert_eq!(module["definitions"][0]["name"], "Result");
}

use rtla::{parse_expression, parse_module};

#[test]
fn qualified_operators_and_instance_substitutions_are_preserved() {
    let source = "---- MODULE Root ----\nVARIABLE x\nA == INSTANCE Counter WITH value <- x, Limit <- 2\nLOCAL INSTANCE Helpers\nInit == A!Init\nNext == A!Next(1)\n====";
    let module = serde_json::to_value(parse_module(source).unwrap()).unwrap();
    assert_eq!(module["instances"][0]["name"], "A");
    assert_eq!(module["instances"][0]["module"], "Counter");
    assert_eq!(module["instances"][0]["substitutions"][0]["name"], "value");
    assert_eq!(module["instances"][1]["isLocal"], true);
    assert_eq!(module["definitions"][0]["body"]["name"], "A!Init");
    assert_eq!(module["definitions"][1]["body"]["operator"], "A!Next");
    let expression = serde_json::to_value(parse_expression("A!B!Apply(1)").unwrap()).unwrap();
    assert_eq!(expression["operator"], "A!B!Apply");
}

#[test]
fn duplicate_instance_substitutions_are_rejected() {
    assert!(
        parse_module(
            "---- MODULE Root ----\nA == INSTANCE Counter WITH Limit <- 1, Limit <- 2\n===="
        )
        .is_err()
    );
}

#[test]
fn symbolic_with_values_stop_at_the_next_module_unit() {
    for following in [
        "Next == TRUE",
        "Next(value) == value",
        "left %% right == left",
        "ASSUME TRUE",
        "THEOREM TRUE",
        "CONSTANT value",
        "RECURSIVE F(_)\nF(value) == value",
        "LOCAL Next == TRUE",
        "INSTANCE Other",
    ] {
        let source =
            format!("---- MODULE Test ----\nI == INSTANCE Symbols WITH ~ <- ~\n{following}\n====");
        let module =
            rtla::parse_module(&source).unwrap_or_else(|error| panic!("{source}: {error}"));
        assert!(
            matches!(&module.instances[0].substitutions[0].expression.node, rtla::ast::ExpressionKind::Identifier { name } if name == "~")
        );
    }
    for spelling in ["\\X", "\\times"] {
        assert!(
            rtla::parse_module(&format!(
                "---- MODULE Test ----\nI == INSTANCE Symbols WITH F <- {spelling}\n===="
            ))
            .is_err()
        );
    }
}

